import{h as t,b as r,c as s,g as m}from"./chunks/framework.Umc73qbk.js";const d=JSON.parse('{"title":"博客已迁移至VitePress","description":"","frontmatter":{"title":"博客已迁移至VitePress","date":"2026-07-04T00:00:00.000Z","tags":["前端","Vue"]},"headers":[],"relativePath":"posts/blog-vitepress-migration/index.md","filePath":"posts/blog-vitepress-migration/index.md"}'),p={name:"posts/blog-vitepress-migration/index.md"};function a(o,e,i,n,_,l){return r(),s("div",null,[...e[0]||(e[0]=[m('<p>忙活了两周，总算迁移过来了！</p><hr><p>去年的这个时候，我使用<a href="https://v2.vuepress.vuejs.org/" target="_blank" rel="noreferrer">vuepress-next</a>搭建了这个博客</p><p>原本博客的主题基于<a href="https://theme-hope.vuejs.press/" target="_blank" rel="noreferrer">vuepress-theme-hope</a>，虽然提供了开箱即用的博客功能，但样式还是不太符合我的口味</p><p>我本想在原本的主题上进一步修改，但我之前对前端一窍不通，让AI大改了一通却越改越奇怪，自己也看不懂AI拉的CSS，于是寻思着能不能找个时机换个主题或者彻底重写一通...</p><p>后面发现VuePress的正统继承者<a href="https://vitepress.dev/" target="_blank" rel="noreferrer">VitePress</a>，它的默认主题更像是一个文档而非博客网站，而现有的第三方主题大多基于默认主题，也不太能满足要求</p><p>但好在VitePress提供了完全自定义主题的能力，那我们只要用他的SSG功能，从零开始构建主题就行</p><hr><p>还是想让自己的博客更有特色一点（可能也有一点情怀在？），最后用了Metro的设计风格并使用Vue编写了主页等组件</p><p>现在的主题还是有点耦合，之后可能会找个时间把主题拆出来公开发布（虽然代码已经在<a href="https://github.com/zxbmmmmmmmmm/zxbmmmmmmmmm.github.io" target="_blank" rel="noreferrer">zxbmmmmmmmmm/zxbmmmmmmmmm.github.io</a>上了）</p>',10)])])}const g=t(p,[["render",a]]);export{d as __pageData,g as default};
